// src/Core/SettingsData.cs
namespace ClothingPairing.Core
{

public class SettingsData
{
    public int Version { get; set; } = 2;
    public bool Enabled { get; set; } = true;
    public bool FashionEnabled { get; set; } = true;
    public bool FacewearEnabled { get; set; } = true;
    public bool RestoreAfterDuty { get; set; } = true;
    public bool RestoreAfterMount { get; set; }
    public bool RestoreAfterCombat { get; set; }
    public bool RestoreAfterZone { get; set; }
    public bool RestoreFacewearAfterClassJob { get; set; } = true;
    public bool RestoreFacewearAfterGearset { get; set; } = true;
    public bool RespectAutoUmbrella { get; set; } = true;
    // Keep original v1 fashion memories and pauses unchanged during migration.
    public Dictionary<ulong, CharacterMemory> Characters { get; set; } = [];
    public Dictionary<ulong, FacewearMemory> FacewearCharacters { get; set; } = [];

    public RestoreOptions ToOptions(AccessoryKind kind) => new(
        Enabled && (kind == AccessoryKind.Fashion ? FashionEnabled : FacewearEnabled),
        (RestoreAfterDuty ? Interruption.Duty : 0) |
        (RestoreAfterMount ? Interruption.Mount : 0) |
        (RestoreAfterCombat ? Interruption.Combat : 0) |
        (RestoreAfterZone ? Interruption.Zone : 0) |
        (kind == AccessoryKind.Facewear && RestoreFacewearAfterClassJob ? Interruption.ClassJob : 0) |
        (kind == AccessoryKind.Facewear && RestoreFacewearAfterGearset ? Interruption.Gearset : 0));

    public CharacterMemory GetMemory(ulong characterId, AccessoryKind kind, int slot = 0)
    {
        if (characterId == 0) throw new ArgumentOutOfRangeException(nameof(characterId));
        if (kind == AccessoryKind.Fashion)
        {
            if (!Characters.TryGetValue(characterId, out var memory))
                Characters[characterId] = memory = new CharacterMemory();
            return memory;
        }
        if (slot != 0) throw new ArgumentOutOfRangeException(nameof(slot));
        if (!FacewearCharacters.TryGetValue(characterId, out var facewear))
            FacewearCharacters[characterId] = facewear = new FacewearMemory();
        return facewear.Slots[slot];
    }

    public void Normalize()
    {
        if (Version > 2)
            throw new InvalidOperationException("配置版本高于本插件支持范围，请使用对应的新版本插件。");
        Characters ??= [];
        FacewearCharacters ??= [];
        foreach (var id in Characters.Where(p => p.Key == 0 || p.Value is null).Select(p => p.Key).ToArray())
            Characters.Remove(id);
        foreach (var id in FacewearCharacters.Where(p => p.Key == 0 || p.Value is null).Select(p => p.Key).ToArray())
            FacewearCharacters.Remove(id);
        foreach (var memory in FacewearCharacters.Values) memory.Normalize();
        Version = 2;
    }
}
}

// src/Core/RestoreController.cs
namespace ClothingPairing.Core
{

/// <summary>Deterministic decision logic; receives monotonic seconds and never accesses native memory.</summary>
public sealed class RestoreController(ulong characterId, CharacterMemory memory)
{
    public const double StableSeconds = 1.2;
    public const double ResultSeconds = 2.0;
    public const double MissingGraceSeconds = 0.8;
    public const int MaximumAttempts = 3;

    private bool wasWearing;
    private bool presenceObserved;
    private bool armed;
    private bool episode;
    private bool awaiting;
    private uint currentId;
    private uint ignoredId;
    private double? missingSince;
    private double? stableSince;
    private double? clearSince;
    private double lastAttempt;
    private string fault = "";

    public ulong CharacterId { get; } = characterId;
    public CharacterMemory Memory { get; } = memory;
    public Interruption Sources { get; private set; }
    public int Attempts { get; private set; }
    public bool HasPendingRequest => episode;
    public bool ConfigurationChanged { get; private set; }
    public RestorePhase Phase { get; private set; }
    public string Status { get; private set; } = "等待玩家佩戴一次配饰";
    public string LastResult { get; private set; } = "尚未请求恢复";

    public void AcknowledgeConfiguration() => ConfigurationChanged = false;

    public void Pause()
    {
        SetPause(true);
        armed = false;
        CancelEpisode();
        Phase = RestorePhase.Paused;
        Status = "已暂停；再次手动佩戴配饰或点击继续可恢复";
    }

    public void RequestRestore()
    {
        SetPause(false);
        fault = "";
        CancelEpisode();
        if (Memory.LastAccessoryId == 0)
        {
            Status = "没有记忆，请先手动佩戴一次配饰";
            return;
        }

        armed = true;
        episode = true;
        Sources = Interruption.Manual;
        Status = "已请求恢复，等待可用";
    }

    public void ClearMemory()
    {
        ignoredId = currentId;
        Memory.LastAccessoryId = 0;
        SetPause(false);
        ConfigurationChanged = true;
        armed = false;
        fault = "";
        missingSince = null;
        CancelEpisode();
        Status = "记忆已清除；下次重新佩戴配饰时记录";
    }

    public void StopForError(string message)
    {
        var attempts = Attempts;
        fault = message;
        CancelEpisode();
        Attempts = attempts;
        armed = false;
        Phase = RestorePhase.Failed;
        Status = message;
        LastResult = message;
    }

    public void Defer(string reason)
    {
        stableSince = null;
        Status = reason;
    }

    // Called only after the adapter actually invokes UseAction, even when it returns false.
    public void Submitted(double now, bool accepted)
    {
        Attempts++;
        lastAttempt = now;
        awaiting = true;
        stableSince = null;
        Phase = RestorePhase.WaitingForResult;
        LastResult = accepted ? "动作请求已接受，等待实际佩戴" : "动作请求返回失败，等待状态确认";
        Status = LastResult;
    }

    public RestoreRequest? Update(GameSnapshot snapshot, RestoreOptions options, double now)
    {
        if (snapshot.CharacterId != CharacterId)
        {
            stableSince = null;
            Phase = RestorePhase.Suspended;
            Status = "等待当前角色数据就绪";
            return null;
        }

        var active = snapshot.Interruptions;
        // Observe the interruption while the accessory is still visible: it can disappear
        // before the next valid local player object exists.
        if (options.Enabled && !Memory.PausedByUser && armed && fault.Length == 0 && active != 0)
        {
            episode = true;
            Sources |= active;
        }

        if (snapshot.AccessoryId is > 0)
        {
            var id = snapshot.AccessoryId.Value;
            currentId = id;
            var appeared = !wasWearing;
            var previouslyObserved = presenceObserved;
            var changed = id != Memory.LastAccessoryId;
            presenceObserved = true;
            wasWearing = true;
            missingSince = null;
            if (id != ignoredId)
            {
                if (changed)
                {
                    Memory.LastAccessoryId = id;
                    ConfigurationChanged = true;
                }
                if ((appeared && previouslyObserved) || changed)
                {
                    SetPause(false);
                    fault = "";
                }
                armed = !Memory.PausedByUser;
                // Existing/new actual accessories always win over queued preferences.
                // During a live interruption retain intent until it has really ended.
                if (changed || appeared || active == Interruption.None)
                {
                    if (episode || awaiting)
                        LastResult = changed ? "已采用新佩戴的配饰，取消旧请求" : "已确认配饰实际佩戴";
                    CancelEpisode();
                }
                if (options.Enabled && armed && active != 0 && fault.Length == 0)
                {
                    episode = true;
                    Sources |= active;
                }
            }
            return ShowPassiveStatus(options);
        }

        if (snapshot.AccessoryId == 0)
        {
            presenceObserved = true;
            currentId = 0;
            ignoredId = 0;
            if (wasWearing)
            {
                wasWearing = false;
                missingSince = now;
            }
        }

        if (!options.Enabled)
        {
            CancelEpisode();
            armed = false;
            missingSince = null;
            Phase = RestorePhase.Disabled;
            Status = "自动恢复已关闭，仍可记录玩家实际使用的配饰";
            return null;
        }
        if (Memory.PausedByUser || fault.Length > 0)
            return ShowPassiveStatus(options);

        if (!episode && armed && active != 0)
        {
            episode = true;
            Sources |= active;
        }
        if (!episode)
        {
            if (armed && missingSince.HasValue && now - missingSince.Value >= MissingGraceSeconds)
            {
                Pause();
                Status = "配饰已移除；未识别到中断，已暂停自动恢复";
            }
            else
            {
                Phase = RestorePhase.Observing;
                Status = Memory.LastAccessoryId == 0 ? "请先手动佩戴一次配饰" : "已记忆，等待配饰使用或有效中断";
            }
            return null;
        }

        if (active != 0 || snapshot.AccessoryId is null || snapshot.BlockReason.Length > 0)
        {
            stableSince = null;
            clearSince = null;
            Phase = awaiting ? RestorePhase.WaitingForResult : RestorePhase.Suspended;
            Status = snapshot.BlockReason.Length > 0 ? snapshot.BlockReason : "等待中断结束与角色状态就绪";
            return null;
        }

        // Allow flags to settle across zone/duty handoffs before rejecting a disabled trigger.
        clearSince ??= now;
        if ((Sources & (options.Triggers | Interruption.Manual)) == 0)
        {
            Phase = RestorePhase.Suspended;
            Status = "此次中断对应的恢复选项未开启";
            if (now - clearSince.Value >= StableSeconds)
            {
                CancelEpisode();
                armed = false;
                missingSince = null;
            }
            return null;
        }

        if (awaiting)
        {
            Phase = RestorePhase.WaitingForResult;
            Status = "等待配饰佩戴结果";
            if (now - lastAttempt < ResultSeconds)
                return null;
            awaiting = false;
            if (Attempts >= MaximumAttempts)
            {
                StopForError("本轮恢复失败三次，已停止；可点击立即恢复重试");
                return null;
            }
        }

        if (snapshot.UnavailableReason.Length > 0)
        {
            stableSince = null;
            Phase = RestorePhase.Suspended;
            Status = snapshot.UnavailableReason;
            return null;
        }

        stableSince ??= now;
        Phase = RestorePhase.Stabilizing;
        Status = "状态已可用，等待稳定后恢复";
        if (now - stableSince.Value < StableSeconds)
            return null;
        return new RestoreRequest(CharacterId, Memory.LastAccessoryId);
    }

    private RestoreRequest? ShowPassiveStatus(RestoreOptions options)
    {
        if (!options.Enabled)
        {
            CancelEpisode();
            armed = false;
            Phase = RestorePhase.Disabled;
            Status = "自动恢复已关闭";
        }
        else if (Memory.PausedByUser)
        {
            Phase = RestorePhase.Paused;
            Status = "已暂停；再次手动佩戴配饰或点击继续可恢复";
        }
        else if (fault.Length > 0)
        {
            Phase = RestorePhase.Failed;
            Status = fault;
        }
        else
        {
            Phase = episode ? RestorePhase.Suspended : RestorePhase.Observing;
            Status = episode ? "已记录中断，等待允许恢复" : "正在观察当前配饰";
        }
        return null;
    }

    private void SetPause(bool paused)
    {
        if (Memory.PausedByUser == paused) return;
        Memory.PausedByUser = paused;
        ConfigurationChanged = true;
    }

    private void CancelEpisode()
    {
        episode = false;
        awaiting = false;
        Sources = Interruption.None;
        Attempts = 0;
        stableSince = null;
        clearSince = null;
    }
}
}

// src/Core/EquipmentChangeTracker.cs
namespace ClothingPairing.Core
{

/// <summary>Observes confirmed context changes, never treats the first session sample as a change.</summary>
public sealed class EquipmentChangeTracker
{
    public const double SettleSeconds = 1.5;
    private ulong characterId;
    private uint? classJobId;
    private int? gearsetIndex;
    private Interruption sources;
    private double until;

    public void Reset()
    {
        characterId = 0;
        classJobId = null;
        gearsetIndex = null;
        sources = Interruption.None;
        until = 0;
    }

    public Interruption Observe(ulong character, uint job, int? gearset, double now)
    {
        if (character == 0) { Reset(); return Interruption.None; }
        if (characterId != character)
        {
            Reset();
            characterId = character;
        }
        if (now >= until) sources = Interruption.None;
        var changed = Interruption.None;
        if (job != 0)
        {
            if (classJobId.HasValue && classJobId != job) changed |= Interruption.ClassJob;
            classJobId = job;
        }
        // null means temporarily unavailable; -1 means no selected gearset.
        // Both may occur during transitions and cannot manufacture a gearset switch.
        if (gearset is >= 0 and < 100)
        {
            if (gearsetIndex.HasValue && gearsetIndex != gearset) changed |= Interruption.Gearset;
            gearsetIndex = gearset;
        }
        if (changed != Interruption.None)
        {
            sources |= changed;
            until = now + SettleSeconds;
        }
        return now < until ? sources : Interruption.None;
    }
}
}

// src/Core/SubmissionArbiter.cs
namespace ClothingPairing.Core
{

// Serialize independent requests and fairly rotate categories and facewear slots.
public sealed class SubmissionArbiter
{
    public const double MinimumInterval = 0.6;
    private int nextIndex;
    private double nextAllowed;

    public int? Select(IReadOnlyList<bool> ready, double now)
    {
        if (now < nextAllowed || ready.Count == 0) return null;
        for (var offset = 0; offset < ready.Count; offset++)
        {
            var index = (nextIndex + offset) % ready.Count;
            if (!ready[index]) continue;
            nextIndex = (index + 1) % ready.Count;
            return index;
        }
        return null;
    }

    public void Submitted(double now) => nextAllowed = now + MinimumInterval;
}
}

// src/Core/FacewearEquipCommand.cs
namespace ClothingPairing.Core
{

// Argument order verified against pinned OmenTools GlassesCommand / ExecuteCommandFlag.
public readonly record struct FacewearEquipCommand(int Slot, int GlassesId)
{
    public const int CommandId = 455;
    public static FacewearEquipCommand Create(int slot, uint glassesId)
    {
        // CN exposes one usable facewear position. A second native array element is
        // not evidence of a player-usable slot, and is never a separate colour slot.
        if (slot != 0) throw new ArgumentOutOfRangeException(nameof(slot));
        if (glassesId is 0 or > ushort.MaxValue) throw new ArgumentOutOfRangeException(nameof(glassesId));
        return new(slot, (int)glassesId);
    }
}
}

// src/Core/MemoryArchive.cs
namespace ClothingPairing.Core
{
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
/// <summary>Per-host memory storage, independent of the host's settings save schedule.</summary>
public sealed class MemoryArchive
{
    public int Version { get; set; } = 2;
    public Dictionary<ulong, CharacterMemory> Characters { get; set; } = [];
    public Dictionary<ulong, FacewearMemory> FacewearCharacters { get; set; } = [];

    public static void Load(string path, SettingsData settings)
    {
        if (!File.Exists(path)) return;
        var normalized = Parse(File.ReadAllText(path));
        settings.Characters = normalized.Characters;
        settings.FacewearCharacters = normalized.FacewearCharacters;
    }

    public static async Task<SettingsData?> ReadAsync(string path, CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if (!File.Exists(path)) return null;
        var json = await File.ReadAllTextAsync(path, cancellationToken).ConfigureAwait(false);
        cancellationToken.ThrowIfCancellationRequested();
        return Parse(json);
    }

    private static SettingsData Parse(string json)
    {
        var archive = JsonSerializer.Deserialize<MemoryArchive>(json)
            ?? throw new InvalidDataException("Empty accessory memory file.");
        var normalized = new SettingsData
        {
            Version = archive.Version,
            Characters = archive.Characters,
            FacewearCharacters = archive.FacewearCharacters,
        };
        normalized.Normalize();
        return normalized;
    }

    public static void Save(string path, SettingsData settings)
    {
        var directory = Path.GetDirectoryName(Path.GetFullPath(path))!;
        Directory.CreateDirectory(directory);
        var temporary = path + ".tmp-" + Guid.NewGuid().ToString("N");
        try
        {
            var json = JsonSerializer.Serialize(new MemoryArchive
            {
                Characters = settings.Characters,
                FacewearCharacters = settings.FacewearCharacters,
            });
            File.WriteAllText(temporary, json, new System.Text.UTF8Encoding(false));
            File.Move(temporary, path, true);
        }
        finally
        {
            if (File.Exists(temporary)) File.Delete(temporary);
        }
    }
}
}

// src/GameAdapter.cs
namespace ClothingPairing
{
using ClothingPairing.Core;
using Dalamud.Game.ClientState.Conditions;
using Dalamud.Plugin.Services;
using FFXIVClientStructs.FFXIV.Client.Game;
using FFXIVClientStructs.FFXIV.Client.Game.Character;
using FFXIVClientStructs.FFXIV.Client.UI.Misc;
using Lumina.Excel.Sheets;
using Ornament = Lumina.Excel.Sheets.Ornament;
public sealed record AccessoryInfo(uint Id, string Name, uint Icon, int Slot = 0);
public readonly record struct Submission(bool Attempted, bool Accepted, string Message);

/// <summary>Only accessed by the framework update callback. Never retains player/native pointers.</summary>
public sealed unsafe class GameAdapter
{
    private readonly IClientState client;
    private readonly IPlayerState player;
    private readonly IObjectTable objects;
    private readonly ICondition conditions;
    private readonly IUnlockState unlocks;
    private readonly IDataManager data;
    private readonly Dictionary<uint, AccessoryInfo> catalog = [];
    private readonly Dictionary<uint, AccessoryInfo> facewearCatalog = [];
    private readonly HashSet<uint> dutyTerritories = [];
    private readonly HashSet<uint> umbrellaIds = [];
    private double zoneUntil;
    private readonly EquipmentChangeTracker equipmentChanges = new();

    private static readonly (ConditionFlag Flag, string Reason)[] BusyConditions =
    [
        (ConditionFlag.Unconscious, "玩家已死亡"),
        (ConditionFlag.Emoting, "正在使用情感动作"),
        (ConditionFlag.Casting, "正在施法"),
        (ConditionFlag.Casting87, "正在施法"),
        (ConditionFlag.Occupied, "玩家忙碌中"),
        (ConditionFlag.Occupied30, "玩家忙碌中"),
        (ConditionFlag.OccupiedInEvent, "正在进行交互"),
        (ConditionFlag.OccupiedInQuestEvent, "正在进行任务交互"),
        (ConditionFlag.Occupied33, "玩家忙碌中"),
        (ConditionFlag.OccupiedInCutSceneEvent, "正在观看剧情"),
        (ConditionFlag.WatchingCutscene, "正在观看剧情"),
        (ConditionFlag.WatchingCutscene78, "正在观看剧情"),
        (ConditionFlag.Occupied38, "玩家忙碌中"),
        (ConditionFlag.Occupied39, "玩家忙碌中"),
        (ConditionFlag.OccupiedSummoningBell, "正在使用传唤铃"),
        (ConditionFlag.Crafting, "正在制作"),
        (ConditionFlag.PreparingToCraft, "正在准备制作"),
        (ConditionFlag.ExecutingCraftingAction, "正在制作"),
        (ConditionFlag.Gathering, "正在采集"),
        (ConditionFlag.ExecutingGatheringAction, "正在采集"),
        (ConditionFlag.Fishing, "正在钓鱼"),
        (ConditionFlag.Jumping, "正在跳跃"),
        (ConditionFlag.Jumping61, "正在跳跃"),
        (ConditionFlag.Diving, "正在潜水"),
        (ConditionFlag.UsingChocoboTaxi, "正在乘坐陆行鸟出租车"),
        (ConditionFlag.LoggingOut, "正在登出"),
        (ConditionFlag.TradeOpen, "正在交易"),
        (ConditionFlag.Performing, "正在演奏"),
        (ConditionFlag.EditingPortrait, "正在编辑肖像"),
        (ConditionFlag.DutyRecorderPlayback, "正在回放任务"),
        (ConditionFlag.RolePlaying, "正在使用剧情角色"),
        (ConditionFlag.Transformed, "玩家处于变身状态"),
        (ConditionFlag.PilotingMech, "正在驾驶机甲"),
    ];

    public GameAdapter(IClientState client, IPlayerState player, IObjectTable objects,
        ICondition conditions, IUnlockState unlocks, IDataManager data)
    {
        this.client = client;
        this.player = player;
        this.objects = objects;
        this.conditions = conditions;
        this.unlocks = unlocks;
        this.data = data;

        foreach (var row in data.GetExcelSheet<Ornament>())
        {
            if (row.RowId == 0 || row.Model == 0) continue;
            catalog[row.RowId] = new(row.RowId, row.Singular.ExtractText(), row.Icon);
        }
        foreach (var row in data.GetExcelSheet<TerritoryType>())
            if (row.ContentFinderCondition.RowId != 0)
                dutyTerritories.Add(row.RowId);
        foreach (var row in data.GetExcelSheet<Glasses>())
        {
            if (row.RowId == 0 || row.RowId > ushort.MaxValue || row.Model == 0 || !row.Style.IsValid) continue;
            var name = row.Name.ExtractText();
            if (string.IsNullOrWhiteSpace(name)) name = row.Singular.ExtractText();
            var slot = row.Style.Value.GlassesSlot;
            if (slot != 0) continue;
            facewearCatalog[row.RowId] = new(row.RowId, name, (uint)Math.Max(0, row.Icon), slot);
        }
    }

    public AccessoryInfo? Find(uint id, AccessoryKind kind = AccessoryKind.Fashion) =>
        (kind == AccessoryKind.Fashion ? catalog : facewearCatalog).GetValueOrDefault(id);
    public void NotifyZoneChange(double now) => zoneUntil = now + 1.5;
    public void ResetSession() => equipmentChanges.Reset();

    public GameSnapshot Capture(double now, uint rememberedId, bool checkAction, bool respectUmbrella,
        AccessoryKind kind = AccessoryKind.Fashion, int slot = 0)
    {
        if (slot != 0) throw new ArgumentOutOfRangeException(nameof(slot));
        var activeCatalog = kind == AccessoryKind.Fashion ? catalog : facewearCatalog;
        var id = player.IsLoaded ? player.ContentId : 0;
        var interruptions = Interruption.None;
        if (conditions[ConditionFlag.BoundByDuty] || conditions[ConditionFlag.BoundByDuty56] ||
            conditions[ConditionFlag.BoundByDuty95] || dutyTerritories.Contains(client.TerritoryType))
            interruptions |= Interruption.Duty;
        if (conditions[ConditionFlag.Mounted] || conditions[ConditionFlag.RidingPillion] ||
            conditions[ConditionFlag.Mounting] || conditions[ConditionFlag.Mounting71] ||
            conditions[ConditionFlag.InFlight])
            interruptions |= Interruption.Mount;
        if (conditions[ConditionFlag.InCombat]) interruptions |= Interruption.Combat;
        if (conditions[ConditionFlag.BetweenAreas] || conditions[ConditionFlag.BetweenAreas51] || now < zoneUntil)
            interruptions |= Interruption.Zone;

        if (!client.IsLoggedIn || id == 0)
        {
            equipmentChanges.Reset();
            return new(id, null, interruptions, "等待登录和角色数据就绪");
        }
        var local = objects.LocalPlayer;
        if (local is null || local.Address == 0)
            return new(id, null, interruptions, "等待玩家对象就绪");
        if (local.EntityId != player.EntityId)
            return new(id, null, interruptions, "等待角色与玩家对象同步");

        var character = (Character*)local.Address;
        if (kind == AccessoryKind.Facewear)
        {
            var gearsets = RaptureGearsetModule.Instance();
            interruptions |= equipmentChanges.Observe(id, local.ClassJob.RowId,
                gearsets == null ? null : gearsets->CurrentGearsetIndex, now);
        }
        var rawId = kind == AccessoryKind.Fashion
            ? (uint)character->OrnamentData.OrnamentId : character->DrawData.GlassesIds[slot];
        var hasAccessory = kind == AccessoryKind.Fashion ? conditions[ConditionFlag.UsingFashionAccessory] : rawId > 0;
        var transition = conditions[ConditionFlag.MountOrOrnamentTransition];
        uint? accessoryId = null;
        // Require condition and ID to agree. An inconsistent transitional sample must
        // neither clear memory nor be interpreted as an intentional unequip.
        if (!transition && hasAccessory && rawId > 0 && activeCatalog.ContainsKey(rawId)) accessoryId = rawId;
        else if (!transition && !hasAccessory && rawId == 0) accessoryId = 0;

        var autoUmbrella = (uint)character->OrnamentData.AutoUmbrellaOrnamentId;
        if (autoUmbrella != 0) umbrellaIds.Add(autoUmbrella);
        var umbrellaConflict = kind == AccessoryKind.Fashion && autoUmbrella != 0 && umbrellaIds.Contains(rememberedId);

        var block = "";
        if ((interruptions & Interruption.Zone) != 0) block = "等待切区结束";
        else if ((interruptions & Interruption.Duty) != 0) block = "等待离开副本";
        else if ((interruptions & Interruption.Mount) != 0) block = "等待下坐骑";
        else if ((interruptions & Interruption.Combat) != 0) block = "等待脱离战斗";
        else if ((interruptions & (Interruption.ClassJob | Interruption.Gearset)) != 0) block = "等待职业与套装切换稳定";
        else if (client.IsPvP) block = "PvP 区域暂停恢复";
        else if (client.IsGPosing) block = "集体姿势模式暂停恢复";
        else if (transition) block = "等待配饰或坐骑动作结束";
        else if (accessoryId is null) block = "等待配饰状态同步";
        else
            foreach (var busy in BusyConditions)
                if (conditions[busy.Flag]) { block = busy.Reason; break; }

        var unavailable = "";
        uint? status = null;
        if (checkAction && rememberedId != 0 && block.Length == 0 && accessoryId == 0)
        {
            if (!activeCatalog.ContainsKey(rememberedId))
                unavailable = "记忆中的配饰不存在于当前客户端";
            else if (kind == AccessoryKind.Facewear)
            {
                var row = data.GetExcelSheet<Glasses>().GetRow(rememberedId);
                if (facewearCatalog[rememberedId].Slot != slot)
                    unavailable = "记忆中的面部配饰与当前槽位不匹配";
                else if (!unlocks.IsGlassesUnlocked(row))
                    unavailable = "当前角色尚未解锁记忆中的面部配饰";
                else if (GameMain.MemberFunctionPointers.ExecuteCommand == null)
                    throw new InvalidOperationException("面部配饰佩戴接口不可用，已停止此槽位自动恢复");
                // Facewear uses a game command, not an ActionType. Do not fabricate an action status.
            }
            else if (!unlocks.IsOrnamentUnlocked(data.GetExcelSheet<Ornament>().GetRow(rememberedId)))
                unavailable = "当前角色尚未解锁记忆中的配饰";
            else if (respectUmbrella && umbrellaConflict)
                unavailable = "已交由游戏自动雨伞控制；可在设置中关闭优先游戏自动雨伞";
            else
            {
                var manager = ActionManager.Instance();
                if (manager is null || ActionManager.MemberFunctionPointers.GetActionStatus == null ||
                    ActionManager.MemberFunctionPointers.UseAction == null)
                    throw new InvalidOperationException("配饰动作接口不可用；已停止自动恢复");
                status = manager->GetActionStatus(ActionType.Ornament, rememberedId);
                if (status != 0) unavailable = "游戏当前不允许使用此配饰（状态码见诊断）";
            }
        }
        return new(id, accessoryId, interruptions, block, unavailable, status, autoUmbrella != 0,
            rawId, hasAccessory, transition);
    }

    public Submission TrySubmit(double now, RestoreRequest request, bool respectUmbrella,
        AccessoryKind kind = AccessoryKind.Fashion, int slot = 0)
    {
        var snapshot = Capture(now, request.AccessoryId, true, respectUmbrella, kind, slot);
        if (snapshot.CharacterId != request.CharacterId || snapshot.AccessoryId != 0 ||
            snapshot.Interruptions != 0 || snapshot.BlockReason.Length > 0 || snapshot.UnavailableReason.Length > 0 ||
            (kind == AccessoryKind.Fashion && snapshot.NativeStatus != 0))
            return new(false, false, "提交前状态改变，继续等待");
        if (kind == AccessoryKind.Facewear)
        {
            var command = FacewearEquipCommand.Create(slot, request.AccessoryId);
            var accepted = GameMain.ExecuteCommand(FacewearEquipCommand.CommandId, command.Slot, command.GlassesId);
            return new(true, accepted, accepted ? "游戏已接受面部配饰佩戴请求" : "游戏拒绝了面部配饰佩戴请求");
        }
        var manager = ActionManager.Instance();
        if (manager is null) return new(false, false, "动作管理器尚未就绪");
        // Regular game action dispatch: no memory writes, unlock changes or forced visuals.
        var result = manager->UseAction(ActionType.Ornament, request.AccessoryId);
        return new(true, result, result ? "游戏已接受展开请求" : "游戏拒绝了展开请求");
    }
}
}

